require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require __DIR__.'/../app/online_fulfillment.php'; require_permission('dispatch_online_orders');
$id=(int)($_GET['id']??$_POST['id']??0);$err='';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{if(!$id||!can_access_online_order($id))throw new Exception('Order outside your location scope.');$courier=trim($_POST['courier']??'');$awb=trim($_POST['awb']??'');$weight=max(0,(float)($_POST['package_weight']??0));if($courier===''||$awb==='')throw new Exception('Courier and AWB/Tracking number are required.');db()->beginTransaction();$st=db()->prepare('SELECT * FROM online_orders WHERE id=? FOR UPDATE');$st->execute([$id]);$o=$st->fetch();if(!$o||$o['status']!=='PACKED')throw new Exception('Only PACKED orders can be dispatched.');$st=db()->prepare("SELECT a.*,ps.status serial_status FROM online_order_allocations a LEFT JOIN product_serials ps ON ps.id=a.serial_id WHERE a.online_order_id=? AND a.status='PACKED' FOR UPDATE");$st->execute([$id]);$alloc=$st->fetchAll();if(!$alloc)throw new Exception('No packed allocations found.');$total=online_order_totals($id);if((float)$total['packed']+0.0001<(float)$total['total'])throw new Exception('Packing is incomplete.');$sl=db()->prepare("INSERT INTO stock_ledger(txn_type,product_id,batch_id,location_id,qty_out,reference_type,reference_id,remarks,created_by) VALUES('ONLINE_DISPATCH',?,?,?,?, 'ONLINE_ORDER',?,?,?)");foreach($alloc as $a){$q=(float)$a['quantity'];$st=db()->prepare('SELECT qty,reserved_qty FROM inventory_balances WHERE product_id=? AND batch_id=? AND location_id=? FOR UPDATE');$st->execute([$a['product_id'],$a['batch_id'],$a['location_id']]);$b=$st->fetch();if(!$b||(float)$b['qty']+0.0001<$q||(float)$b['reserved_qty']+0.0001<$q)throw new Exception('Reserved stock mismatch. Stop dispatch and audit stock.');db()->prepare('UPDATE inventory_balances SET qty=qty-?,reserved_qty=reserved_qty-? WHERE product_id=? AND batch_id=? AND location_id=?')->execute([$q,$q,$a['product_id'],$a['batch_id'],$a['location_id']]);db()->prepare('UPDATE batches SET qty_available=qty_available-? WHERE id=?')->execute([$q,$a['batch_id']]);if($a['serial_id']){$up=db()->prepare("UPDATE product_serials SET status='SOLD' WHERE id=? AND status='RESERVED'");$up->execute([$a['serial_id']]);if($up->rowCount()!==1)throw new Exception('Reserved garment status changed.');}$sl->execute([$a['product_id'],$a['batch_id'],$a['location_id'],$q,$id,$o['order_no'].' · '.$awb,current_user()['id']]);maybe_publish_low_stock((int)$a['product_id'],(int)$a['location_id']);}db()->prepare("UPDATE online_order_allocations SET status='DISPATCHED' WHERE online_order_id=? AND status='PACKED'")->execute([$id]);db()->prepare("UPDATE online_orders SET status='DISPATCHED',courier=?,awb=?,package_weight=?,dispatched_by=?,dispatched_at=NOW() WHERE id=?")->execute([$courier,$awb,$weight,current_user()['id'],$id]);db()->commit();audit('ONLINE_ORDER_DISPATCH','online_order',$id,['courier'=>$courier,'awb'=>$awb]);publish_event('ONLINE_DISPATCH','Online order dispatched',$o['order_no'].' · '.$courier.' · '.$awb,['super_admin'],'online_order',$id,null);publish_scoped_event('ONLINE_DISPATCH','Order dispatched',$o['order_no'].' · '.$awb,['manager','godown'],'online_order',$id);$msg='Order dispatched and physical stock deducted.';}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
if(!$id){$ids=is_super_admin()?[]:assigned_location_ids();$args=[];$scope='';if(!is_super_admin()){if(!$ids)$scope=' AND 1=0';else{$ph=implode(',',array_fill(0,count($ids),'?'));$scope=" AND NOT EXISTS(SELECT 1 FROM online_order_allocations x WHERE x.online_order_id=o.id AND x.location_id NOT IN ($ph))";$args=$ids;}}$st=db()->prepare("SELECT o.* FROM online_orders o WHERE o.status='PACKED'".$scope.' ORDER BY o.id');$st->execute($args);$queue=$st->fetchAll();page_header('Dispatch Queue');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>';echo '<table><tr><th>Order</th><th>Customer</th><th>Amount</th><th></th></tr>';foreach($queue as $q)echo '<tr><td>'.e($q['order_no']).'</td><td>'.e($q['customer_name']).'</td><td>₹'.e(number_format((float)$q['order_amount'],2)).'</td><td><a class="btn" href="online_dispatch.php?id='.(int)$q['id'].'">Dispatch</a></td></tr>';echo '</table>';page_footer();exit;}
if(!can_access_online_order($id)){http_response_code(403);exit('Order outside your location scope.');}$st=db()->prepare('SELECT * FROM online_orders WHERE id=?');$st->execute([$id]);$o=$st->fetch();if(!$o)exit('Order not found');page_header('Dispatch · '.e($o['order_no']));if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<div class="panel"><b>Customer:</b> <?=e($o['customer_name'])?> · <?=e($o['customer_mobile'])?><br><b>Address:</b> <?=e($o['shipping_address'])?><br><b>Order Amount:</b> ₹<?=e(number_format((float)$o['order_amount'],2))?> · <?=e($o['payment_status'])?></div><br><?php if($o['status']==='PACKED'):?><form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="row3"><div><label>Courier</label><input name="courier" required></div><div><label>AWB / Tracking No.</label><input name="awb" required></div><div><label>Package Weight Kg</label><input type="number" min="0" step="0.001" name="package_weight"></div></div><br><button class="btn">DISPATCH & FINAL DEDUCT STOCK</button></form><?php else:?><div class="notice">Current status: <?=e($o['status'])?><?php if($o['awb']):?> · <?=e($o['courier'].' · '.$o['awb'])?><?php endif;?></div><?php endif;?><?php page_footer();
